-- Generated by tools/reference/import.cs from pinned source files: change that script, not this file.
-- The codes a chart entry can be picked from. Applied as ehr_owner after db/policies; safe to run again: it
-- leaves ehr.clinical_codes holding exactly these rows. A diagnosis is sensitive by its code's range
-- (ehr.icd10cm_is_sensitive, db/policies/65-chart-lists.sql). Sources, versions, licenses and attribution:
-- docs/expansion/reference-data.md.
BEGIN;
CREATE TEMPORARY TABLE incoming_codes (kind text, system text, code text, display text, category text) ON COMMIT DROP;
SELECT kind, system, code, display, category, kind = 'condition' AND ehr.icd10cm_is_sensitive(code) FROM incoming_codes
ON CONFLICT (kind, system, code) DO UPDATE
    SET display = EXCLUDED.display, category = EXCLUDED.category, sensitive = EXCLUDED.sensitive
    WHERE (clinical_codes.display, clinical_codes.category, clinical_codes.sensitive)
        IS DISTINCT FROM (EXCLUDED.display, EXCLUDED.category, EXCLUDED.sensitive);
DELETE FROM ehr.clinical_codes c
WHERE NOT EXISTS (SELECT 1 FROM incoming_codes i WHERE i.kind = c.kind AND i.system = c.system AND i.code = c.code);
COMMIT;
